mapper.select:
SELECT COUNT(*)
FROM ai_agent a
JOIN ai_agent_persona ap ON ap.agent_id = a.id
WHERE a.id = #{agentId}
  AND CAST(a.user_id AS CHAR) = #{userId}
  AND ap.persona_source_id = #{personaId}

mapper.update:
UPDATE ai_companion_state
SET emotion_json = #{emotionJson},
    relationship_json = #{relationshipJson},
    revision = #{revision},
    updated_at = NOW()
WHERE user_id = #{userId}
  AND agent_id = #{agentId}
  AND persona_id = #{personaId}
  AND revision = #{expectedRevision}

mapper.insert:
INSERT IGNORE INTO ai_companion_event(
    turn_id, user_id, agent_id, persona_id, event_type, payload_json, payload_hash, confidence
) VALUES(
    #{turnId}, #{userId}, #{agentId}, #{personaId}, #{eventType}, #{payloadJson}, #{payloadHash}, #{confidence}
)

mapper.update:
UPDATE ai_companion_memory
SET status = 'superseded'
WHERE user_id = #{userId}
  AND agent_id = #{agentId}
  AND persona_id = #{personaId}
  AND memory_type = #{memoryType}
  AND subject_key = #{subjectKey}
  AND NOT normalized_hash = #{normalizedHash}
  AND status = 'active'

mapper.select:
SELECT id
FROM ai_companion_memory
WHERE user_id = #{userId}
  AND agent_id = #{agentId}
  AND persona_id = #{personaId}
  AND memory_type = #{memoryType}
  AND normalized_hash = #{normalizedHash}
LIMIT 1

mapper.update:
UPDATE ai_companion_memory
SET superseded_by = #{supersededBy}
WHERE user_id = #{userId}
  AND agent_id = #{agentId}
  AND persona_id = #{personaId}
  AND memory_type = #{memoryType}
  AND subject_key = #{subjectKey}
  AND NOT normalized_hash = #{normalizedHash}
  AND status = 'superseded'
  AND superseded_by IS NULL

mapper.select:
SELECT COUNT(*) FROM ai_companion_memory
WHERE user_id = #{userId} AND agent_id = #{agentId} AND persona_id = #{personaId}
  AND status = 'active' AND (expires_at IS NULL OR expires_at > NOW())
